{
  "name": "locate.now",
  "version": "1.0.1",
  "license": "MIT",
  "description": "A simple API for IP address & geolocation lookup.",
  "author": {
    "name": "Nikolaos Kamarinakis",
    "url": "nikolaskama.me",
    "email": "nikolaskam@gmail.com"
  },
  "main": "index.js",
  "scripts": {
    "start": "node index.js"
  },
  "dependencies": {
    "body-parser": "^1.18.2",
    "cookie-session": "^2.0.0-beta.3",
    "dotenv": "^5.0.0",
    "express": "^4.16.2",
    "geoip-lite": "^1.2.1",
    "helmet": "^3.11.0"
  },
  "devDependencies": {
    "nodemon": "^1.14.6"
  }
}

var app           = require('express')();
var path          = require('path');
var bodyParser    = require('body-parser');
var cookieSession = require('cookie-session')
var geoip         = require('geoip-lite');
var helmet        = require('helmet');
var dotenv        = require('dotenv')

app.use(bodyParser.json());
app.use(bodyParser.urlencoded({
    extended: false
}));

app.disable('x-powered-by')
app.use(helmet());
dotenv.load();
app.use(cookieSession({
    secret: process.env.SECRET,
    cookie: {
        maxAge:60000,
        httpOnly: true,
        secure: true
    }
}));

app.get('/', function(req, res) {
    res.sendFile(path.join(__dirname + '/index.html'));
});

app.get('/ip', function(req, res) {
	var ipAddress = req.headers['x-forwarded-for'] || req.connection.remoteAddress;
    res.send(ipAddress)
});

app.get('/ip/:type', function(req, res) {
	var ipAddress = req.headers['x-forwarded-for'] || req.connection.remoteAddress;
    if (req.params.type === 'json') {
    	res.json({'ip': ipAddress})
    } else if (req.params.type === 'jsonp') {
    	res.send('callback({"ip":'+ JSON.stringify(ipAddress) + '});');
    }
});

app.get('/ip/:type/:callback', function(req, res) {
    var ipAddress = req.headers['x-forwarded-for'] || req.connection.remoteAddress;
    if (req.params.type === 'jsonp') {
        res.send(req.params.callback + '({"ip":'+ JSON.stringify(ipAddress) + '});');
    }
});

app.get('/geo', function(req, res) {
	var ipAddress = req.headers['x-forwarded-for'] || req.connection.remoteAddress;
    var geo = geoip.lookup(ipAddress);
    res.json(geo);
});

app.use(function (err, req, res, next) {
    console.log(err)
    res.status(500).send('Something broke!')
});

const port = process.env.PORT || 3000;
app.listen(port);
